    <span>‹</span><span class="lbl">Prev</span>
  </button>
  <div class="nav-counter"><span class="cur" id="navCur">I</span> / <span id="navTotal">VIII</span></div>
  <div class="nav-dots" id="navDots"></div>
  <button class="nav-btn nav-btn-next" id="btnNext" onclick="goPage(curPage+1)">
    <span class="lbl">Next</span><span>›</span>
  </button>
