<script>
// ==========================================================
// Hệ thống trang
// ==========================================================
let curPage = 0;
const TOTAL = 5;
const track = document.getElementById('pagesTrack');
const pages = document.querySelectorAll('.page');
const romanNums = ['I','II','III','IV','V','VI','VII','VIII'];

const dotsWrap = document.getElementById('navDots');
for(let i = 0; i < TOTAL; i++){
  const d = document.createElement('div');
  d.className = 'nav-dot' + (i === 0 ? ' active' : '');
  d.onclick = () => goPage(i);
  dotsWrap.appendChild(d);
}

function goPage(idx){
  idx = Math.max(0, Math.min(TOTAL - 1, idx));
  if(idx === curPage) return;
  curPage = idx;
  track.style.transform = `translateX(-${idx * (100 / TOTAL)}%)`;
  pages.forEach((p, i) => p.classList.toggle('active', i === idx));
  pages[idx].scrollTop = 0;
  updateUI();
}

function updateUI(){
  const pct = Math.round((curPage / (TOTAL - 1)) * 100);
  document.getElementById('topBarFill').style.width = pct + '%';
  document.getElementById('topPct').textContent = romanNums[curPage] + ' / VIII';
  document.getElementById('navCur').textContent = romanNums[curPage];
  document.querySelectorAll('.nav-dot').forEach((d, i) => d.classList.toggle('active', i === curPage));
  document.getElementById('btnPrev').disabled = (curPage === 0);
  document.getElementById('btnNext').disabled = (curPage === TOTAL - 1);
  document.getElementById('sideLeft').disabled = (curPage === 0);
  document.getElementById('sideRight').disabled = (curPage === TOTAL - 1);
}
updateUI();

/* ===== Điều khiển nhạc, giữ cùng cơ chế với trang chủ gốc ===== */
let _musicPlaying = false;

function toggleMusic() {
  const audio = document.getElementById('bgMusic');
  const btn   = document.getElementById('musicBtn');
  if (_musicPlaying) {
    audio.pause();
    _musicPlaying = false;
    btn.textContent = '♪';
    btn.classList.remove('playing');
    btn.classList.add('stopped');
  } else {
    audio.play().then(() => {
      _musicPlaying = true;
      btn.textContent = '♫';
      btn.classList.add('playing');
      btn.classList.remove('stopped');
    });
  }
}

function onMusicEnd() {
  _musicPlaying = false;
  const btn = document.getElementById('musicBtn');
  btn.textContent = '♪';
  btn.classList.remove('playing');
  btn.classList.add('stopped');
}

function tryAutoplayMusic() {
  const audio = document.getElementById('bgMusic');
  if (!audio) return;
  audio.volume = 0.65;
  audio.addEventListener('ended', onMusicEnd);

  function _doPlay() {
    audio.play().then(() => {
      _musicPlaying = true;
      const btn = document.getElementById('musicBtn');
      if (btn) { btn.textContent = '♫'; btn.classList.add('playing'); btn.classList.remove('stopped'); }
    }).catch(() => {});
  }

  // Gọi trực tiếp play(); môi trường ST Electron/WebView thường chạy được
  audio.play().then(() => {
    _musicPlaying = true;
    const btn = document.getElementById('musicBtn');
    if (btn) { btn.textContent = '♫'; btn.classList.add('playing'); btn.classList.remove('stopped'); }
  }).catch(() => {
    // Nếu bị chặn, đợi cử chỉ người dùng đầu tiên rồi tự kích hoạt
    ['touchstart', 'touchend', 'click'].forEach(type => {
      document.addEventListener(type, _doPlay, { once: true, passive: true });
    });
    const hint = document.getElementById('musicHint');
    if (hint) { hint.classList.add('show'); setTimeout(() => hint.classList.remove('show'), 5000); }
  });
}

window.addEventListener('DOMContentLoaded', tryAutoplayMusic);

// Chuyển trang bằng phím mũi tên; phím AD đã tắt, vẫn có thể bấm để đổi trang
document.addEventListener('keydown', e => {
  if(e.key === 'ArrowLeft') goPage(curPage - 1);
  else if(e.key === 'ArrowRight') goPage(curPage + 1);
  else if(e.key === 'Home') goPage(0);
  else if(e.key === 'End') goPage(TOTAL - 1);
});

// Vuốt cảm ứng
let touchStartX = 0, touchStartY = 0;
const pagesWrap = document.querySelector('.pages-wrap');
pagesWrap.addEventListener('touchstart', e => {
  touchStartX = e.changedTouches[0].screenX;
  touchStartY = e.changedTouches[0].screenY;
}, {passive: true});
pagesWrap.addEventListener('touchend', e => {
  const dx = e.changedTouches[0].screenX - touchStartX;
  const dy = e.changedTouches[0].screenY - touchStartY;
  if(Math.abs(dx) > 60 && Math.abs(dx) > Math.abs(dy) * 1.5){
    if(dx < 0) goPage(curPage + 1);
    else goPage(curPage - 1);
  }
}, {passive: true});

// Chuyển trang bằng con lăn
let wheelLock = false;
pagesWrap.addEventListener('wheel', e => {
  const curEl = pages[curPage];
  const canScrollY = curEl.scrollHeight > curEl.clientHeight;
  if(canScrollY){
    const atTop = curEl.scrollTop <= 0;
    const atBottom = curEl.scrollTop + curEl.clientHeight >= curEl.scrollHeight - 2;
    if((e.deltaY < 0 && !atTop) || (e.deltaY > 0 && !atBottom)) return;
  }
  if(Math.abs(e.deltaX) > Math.abs(e.deltaY)){
    if(wheelLock) return;
    wheelLock = true;
    if(e.deltaX > 0) goPage(curPage + 1);
    else goPage(curPage - 1);
    setTimeout(() => wheelLock = false, 800);
  }
}, {passive: true});

