let cdTotal = 99 * 24 * 3600 + 23 * 3600 + 59 * 60;
function updateCountdown(){
  const days = Math.floor(cdTotal / 86400);
  const hours = Math.floor((cdTotal % 86400) / 3600);
  const mins = Math.floor((cdTotal % 3600) / 60);
  document.getElementById('cdDays').textContent = String(days).padStart(2,'0');
  document.getElementById('cdHours').textContent = String(hours).padStart(2,'0');
  document.getElementById('cdMins').textContent = String(mins).padStart(2,'0');
}
setInterval(() => { cdTotal = Math.max(0, cdTotal - 1); updateCountdown(); }, 1000);
updateCountdown();

