function showToast(msg){
  const t = document.getElementById('toast');
  t.textContent = msg;
  t.classList.add('show');
  setTimeout(() => t.classList.remove('show'), 2800);
}

function startChronicle(){
  // Thu thập dữ liệu biểu mẫu
  const name = document.getElementById('charName').value.trim() || 'Fujimaru Ritsuka';
  const gender = document.getElementById('charGender').value;
  const age = document.getElementById('charAge').value || '18';
  const background = document.getElementById('charBackground').value.trim() || 'Không';

  const skillName = document.getElementById('divineSkillName').value.trim() || 'Vòng hào quang dục vọng';
  const skillDesc = document.getElementById('divineSkillDesc').value.trim() || 'Kỹ năng chủ động';
  const skillEffect = document.getElementById('divineSkillEffect').value.trim() || 'Sau khi sử dụng, phụ nữ trong phạm vi 20 mét sẽ bị cưỡng chế phát tình với ngự chủ';

  const msg = `【Biên niên sử Vực Nứt · bắt đầu cốt truyện】

═══ Hệ thống nhân vật chính sử dụng VariableEdit để thay đổi dữ liệu sau ═══
"Họ tên"：${name}
"Giới tính"：${gender}
"Tuổi"：${age} tuổi
"Bối cảnh thân phận"：${background}
"Độ khó"：${selectedDifficulty}

═══ Thông tin linh cơ sử dụng VariableInsert để thay đổi dữ liệu sau ═══
Servant đi cùng：${selectedServant}（${selectedServantClass}）
"Kỹ năng sắc lang của Sáng Thế Thần"：${skillName}
"Mô tả kỹ năng"：${skillDesc}
"Hiệu ứng kỹ năng"：${skillEffect}

═══ Khởi động chứng kiến ═══
Bắt đầu tại Chaldea và Điểm Giao Thoa Hỗn Độn.`;

  // 1. Hệ thống nhân vật chính - VariableEdit
  // Trường tên dùng placeholder {{user}} của SillyTavern, được runtime của Tavern tự thay bằng tên người dùng hiện tại
  const protagonistJson = JSON.stringify({
    "Hệ thống nhân vật chính": {
      "Họ tên": "{{user}}",
      "Giới tính": gender,
      "Tuổi": parseInt(age),
      "Bối cảnh thân phận": background,
      "Độ khó": selectedDifficulty
    }
  }, null, 2);
  const varEdit = '<VariableEdit>\n' + protagonistJson + '\n</VariableEdit>';

  // 2. Kỹ năng Sáng Thế Thần - VariableInsert
  const skillObj = {};
  skillObj[skillName] = {
    "Mô tả kỹ năng": skillDesc,
    "Hiệu ứng kỹ năng": skillEffect
  };
  const skillJson = JSON.stringify({
    "Kỹ năng sắc lang của Sáng Thế Thần": skillObj
  }, null, 2);
  const varInsert = '<VariableInsert>\n' + skillJson + '\n</VariableInsert>';

  // Gộp toàn bộ nội dung thành một tin nhắn
  const fullText = msg + '\n\n' + varEdit + '\n\n' + varInsert;

  // Chỉ gửi vào ô nhập tin nhắn dưới cùng của SillyTavern #send_textarea (không tự bấm gửi)
  // SillyTavern dùng component có điều khiển của Vue/React, bắt buộc phải dùng setter gốc để kích hoạt cập nhật trạng thái của framework
  function setNativeValue(el, val){
    try {
      const setter = Object.getOwnPropertyDescriptor(
        el instanceof HTMLInputElement ? window.HTMLInputElement.prototype : window.HTMLTextAreaElement.prototype,
        'value'
      ).set;
      setter.call(el, val);
    } catch(e) { el.value = val; }
  }

  function triggerFullEvents(el){
    const evtTypes = ['input','change','keyup','keydown'];
    for(const type of evtTypes){
      el.dispatchEvent(new Event(type, {bubbles:true, cancelable:true}));
      el.dispatchEvent(new InputEvent('input', {bubbles:true, cancelable:true, data:el.value, inputType:'insertText'}));
    }
    // Lớp tương thích jQuery
    if(typeof $ !== 'undefined' && $(el).length){
      $(el).trigger('input').trigger('change').trigger('keyup');
    }
  }

  let sent = false;

  // Cách 1: tài liệu hiện tại
  const candidates = [
    () => document.querySelector('#send_textarea'),
    () => document.querySelector('textarea#send_textarea'),
    () => document.querySelector('textarea[placeholder*="Type a message"]'),
    () => document.querySelector('textarea[placeholder*="message"]'),
    () => document.querySelector('textarea.mdHotkeys'),
  ];

  // Cách 2: tài liệu cha (cửa sổ chính SillyTavern)
  const parentDocs = [];
  try {
    if(window.parent && window.parent !== window) parentDocs.push(window.parent.document);
    if(window.opener) parentDocs.push(window.opener.document);
    // Thử nhiều lớp lồng nhau
    if(window.parent && window.parent.parent && window.parent.parent !== window.parent)
      parentDocs.push(window.parent.parent.document);
  } catch(e) {}

  const allTargets = [...candidates];
  for(const pd of parentDocs){
    allTargets.push(
      () => pd?.querySelector('#send_textarea'),
      () => pd?.querySelector('textarea#send_textarea'),
      () => pd?.querySelector('textarea[placeholder]'),
      () => pd?.querySelector('textarea.mdHotkeys')
    );
  }

  for(const getEl of allTargets){
    try {
      const inp = getEl();
      if(!inp || !inp.tagName) continue;

      // Dùng setter gốc để đặt giá trị, tránh bị component có điều khiển của Vue/React chặn
      setNativeValue(inp, fullText);

      // Kích hoạt đầy đủ chuỗi sự kiện
      triggerFullEvents(inp);

      // Focus phần tử để người dùng nhìn thấy thay đổi
      inp.focus();
      inp.setSelectionRange(fullText.length, fullText.length);

      showToast('✦ Đã điền vào ô nhập tin nhắn');
      sent = true;

      // Thông tin debug, có thể xem trong console trình duyệt
      console.log('[Biên niên sử Vực Nứt] Đã điền #send_textarea, độ dài:', fullText.length, ', phần tử:', inp.className);
      break;
    } catch(e) { console.warn('[Biên niên sử Vực Nứt] Ứng viên thất bại:', e.message); continue; }
  }

  // Phương án dự phòng
  if(!sent){
    if (typeof sendUserMessage === 'function') {
      sendUserMessage(fullText);
      showToast('✦ Đã bắt đầu chứng kiến');
    } else if (typeof triggerSlash === 'function') {
      triggerSlash('/send ' + fullText);
      showToast('✦ Đã bắt đầu chứng kiến');
    } else {
      alert('Đã tạo lệnh cốt truyện (vui lòng tự dán):\n\n' + fullText);
    }
  }
}
